const express = require('express');
const path = require('path');
const fs = require('fs').promises;
const crypto = require('crypto');
const argon2 = require('argon2');

const app = express();
app.use(express.json());

// Secure document storage service
const DOCS_ROOT = path.resolve('/var/app/documents');
const SESSIONS = new Map();

// Rate limiting
const rateLimiter = new Map();
function rateLimit(ip) {
  const now = Date.now();
  const entry = rateLimiter.get(ip) || { count: 0, resetAt: now + 60000 };
  if (now > entry.resetAt) { entry.count = 0; entry.resetAt = now + 60000; }
  entry.count++;
  rateLimiter.set(ip, entry);
  return entry.count <= 100;
}

// Authentication middleware
async function authenticate(req, res, next) {
  const sessionId = req.headers['x-session-id'];
  if (!sessionId || typeof sessionId !== 'string') {
    return res.status(401).json({ error: 'Authentication required' });
  }
  const session = SESSIONS.get(sessionId);
  if (!session || session.expiresAt < Date.now()) {
    SESSIONS.delete(sessionId);
    return res.status(401).json({ error: 'Session expired' });
  }
  req.user = session.user;
  next();
}

// Path validation - prevents directory traversal
function validateDocPath(userPath) {
  if (typeof userPath !== 'string' || userPath.length === 0 || userPath.length > 255) {
    return null;
  }
  // Reject obvious traversal attempts
  if (userPath.includes('..') || userPath.includes('\\')) {
    return null;
  }
  // Normalize unicode to NFC form for consistent handling
  const normalized = userPath.normalize('NFC');
  // Only allow alphanumeric, hyphens, underscores, dots, and forward slashes
  if (!/^[a-zA-Z0-9_\-\.\/]+$/.test(normalized)) {
    return null;
  }
  // Resolve the full path
  const fullPath = path.resolve(DOCS_ROOT, normalized);
  // Verify it's within DOCS_ROOT
  if (!fullPath.startsWith(DOCS_ROOT + path.sep)) {
    return null;
  }
  return fullPath;
}

// Login endpoint
app.post('/api/login', async (req, res) => {
  if (!rateLimit(req.ip)) return res.status(429).json({ error: 'Rate limited' });
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid credentials format' });
  }
  try {
    const userRecord = await loadUser(username);
    if (!userRecord) return res.status(401).json({ error: 'Invalid credentials' });
    const valid = await argon2.verify(userRecord.passwordHash, password);
    if (!valid) return res.status(401).json({ error: 'Invalid credentials' });
    const sessionId = crypto.randomBytes(32).toString('hex');
    SESSIONS.set(sessionId, {
      user: { id: userRecord.id, username: userRecord.username, role: userRecord.role },
      expiresAt: Date.now() + 3600000
    });
    res.json({ sessionId });
  } catch (e) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Document retrieval - the core functionality
app.get('/api/documents/:docPath(*)', authenticate, async (req, res) => {
  if (!rateLimit(req.ip)) return res.status(429).json({ error: 'Rate limited' });

  const requestedPath = req.params.docPath;
  const validatedPath = validateDocPath(requestedPath);

  if (!validatedPath) {
    return res.status(400).json({ error: 'Invalid document path' });
  }

  // Access control: users can only access their own directory or shared
  const relativePath = path.relative(DOCS_ROOT, validatedPath);
  const topDir = relativePath.split(path.sep)[0];

  if (topDir !== req.user.username && topDir !== 'shared' && req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Access denied' });
  }

  try {
    const content = await fs.readFile(validatedPath, 'utf-8');
    res.json({ content, path: relativePath });
  } catch (e) {
    if (e.code === 'ENOENT') return res.status(404).json({ error: 'Document not found' });
    res.status(500).json({ error: 'Internal error' });
  }
});

// Document write
app.put('/api/documents/:docPath(*)', authenticate, async (req, res) => {
  if (!rateLimit(req.ip)) return res.status(429).json({ error: 'Rate limited' });

  const requestedPath = req.params.docPath;
  const validatedPath = validateDocPath(requestedPath);

  if (!validatedPath) {
    return res.status(400).json({ error: 'Invalid document path' });
  }

  const relativePath = path.relative(DOCS_ROOT, validatedPath);
  const topDir = relativePath.split(path.sep)[0];

  if (topDir !== req.user.username && req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Access denied' });
  }

  const { content } = req.body;
  if (typeof content !== 'string' || content.length > 1048576) {
    return res.status(400).json({ error: 'Invalid content' });
  }

  try {
    await fs.mkdir(path.dirname(validatedPath), { recursive: true });
    await fs.writeFile(validatedPath, content, 'utf-8');
    res.json({ success: true, path: relativePath });
  } catch (e) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Simulated user database
async function loadUser(username) {
  const users = {
    'alice': { id: 1, username: 'alice', role: 'user', passwordHash: '$argon2id$v=19$m=65536,t=3,p=4$c29tZXNhbHQ$hash1' },
    'bob': { id: 2, username: 'bob', role: 'user', passwordHash: '$argon2id$v=19$m=65536,t=3,p=4$c29tZXNhbHQ$hash2' },
    'admin': { id: 3, username: 'admin', role: 'admin', passwordHash: '$argon2id$v=19$m=65536,t=3,p=4$c29tZXNhbHQ$hash3' }
  };
  return users[username] || null;
}

